-- Passage rg5-figurative-language-p05
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('40ee821a-033c-5050-8a63-60585f5cb2bf', 'rg5-figurative-language-p05', (select id from public.skills where slug = 'read-g5-figurative-language'), null,
        '3-5', $q$New Street, New Friend$q$, $q$When Amara Osei's family moved to a new city, she felt like a fish out of water. The streets were loud, the buildings were tall, and she did not know a single person. Her new apartment was a maze of boxes.

On Saturday, her mother asked her to walk their dog, Pepper, around the block. Amara grumbled but clipped on the leash. Across the street, a boy about her age was shooting baskets at the park. His name was Luca.

Pepper tugged Amara straight toward the court. Luca laughed and tossed her the ball. "Want to play?" he asked. Amara hesitated. She was not very good at basketball. Still, she decided to give it a shot.

Her first throw missed the hoop by a mile. Luca did not tease her. Instead, he showed her how to bend her knees and aim. By sunset, she had made five baskets. Luca told her that a few other kids played there every evening.

Walking home, Amara realized the city did not feel so strange after all. Her mother always said that every cloud has a silver lining. Moving had been hard, but it had led her to a new friend.$q$, 'draft')
